package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsC decimal.Decimal // PIC S9(3)V99 len=5 = 0
var WsFreeze int64 // PIC 99 len=2 = 0
var WsCount int64 // PIC 99 len=2 = 0
var WsFEd string // PIC ZZ9.9 len=5
var WsCEd string // PIC -ZZ9.99 len=7

var TempRecData TempRec

var tempReader *bufio.Reader
var tempFile *os.File

func formatPicZZ9(intVal int64, pic []byte) string {
	n := len(pic)
	digits := make([]byte, n)
	tmp := intVal
	for i := n - 1; i >= 0; i-- {
		digits[i] = byte(tmp % 10)
		tmp /= 10
	}
	firstNZ := -1
	for i := 0; i < n; i++ {
		if digits[i] != 0 {
			firstNZ = i
			break
		}
	}
	var sb strings.Builder
	if firstNZ == -1 {
		for i := 0; i < n; i++ {
			if pic[i] == 'Z' {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte('0' + digits[i])
			}
		}
		return sb.String()
	}
	for i := 0; i < n; i++ {
		if i < firstNZ {
			if pic[i] == 'Z' {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte('0' + digits[i])
			}
		} else {
			sb.WriteByte('0' + digits[i])
		}
	}
	return sb.String()
}

func formatFEd(v decimal.Decimal) string {
	neg := v.Sign() < 0
	av := v
	if neg {
		av = v.Neg()
	}
	t := av.Truncate(1)
	scaled := t.Shift(1).IntPart()
	if scaled < 0 {
		scaled = -scaled
	}
	intPart := (scaled / 10) % 1000
	frac := scaled % 10
	intStr := formatPicZZ9(intPart, []byte{'Z', 'Z', '9'})
	return intStr + "." + string([]byte{'0' + byte(frac)})
}

func formatCEd(v decimal.Decimal) string {
	neg := v.Sign() < 0
	av := v
	if neg {
		av = v.Neg()
	}
	t := av.Truncate(2)
	scaled := t.Shift(2).IntPart()
	if scaled < 0 {
		scaled = -scaled
	}
	intPart := (scaled / 100) % 1000
	frac := scaled % 100
	sign := ' '
	if neg {
		// if truncated value is zero, COBOL would show positive? keep sign only if non-zero
		if scaled != 0 {
			sign = '-'
		}
	}
	intStr := formatPicZZ9(intPart, []byte{'Z', 'Z', '9'})
	f0 := byte(frac / 10)
	f1 := byte(frac % 10)
	return string([]byte{byte(sign)}) + intStr + "." + string([]byte{'0' + f0, '0' + f1})
}

func formatPic99(v int64) string {
	m := v % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseImplied(s string, scale int32) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.New(0, 0)
	}
	neg := false
	if strings.HasPrefix(t, "-") || strings.HasPrefix(t, "+") {
		if strings.HasPrefix(t, "-") {
			neg = true
		}
		t = t[1:]
	}
	// remove any '.' if present (should not be)
	t = strings.ReplaceAll(t, ".", "")
	t = strings.TrimSpace(t)
	if t == "" {
		return decimal.New(0, 0)
	}
	var n int64
	for i := 0; i < len(t); i++ {
		c := t[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		}
	}
	if neg {
		n = -n
	}
	return decimal.New(n, scale)
}

func READPARA() {
	line, err := tempReader.ReadString('\n')
	if err != nil {
		// check if we got data before EOF
		if len(line) > 0 {
			// process partial last line
			line = strings.TrimRight(line, "\r\n")
			rec := padRight(line, 8)
			TempRecData.TcSensor = rec[0:4]
			TempRecData.TcF = parseImplied(rec[4:8], 1)
			return
		}
		WsEofFlag = "Y"
		return
	}
	line = strings.TrimRight(line, "\r\n")
	rec := padRight(line, 8)
	TempRecData.TcSensor = rec[0:4]
	TempRecData.TcF = parseImplied(rec[4:8], 1)
}

func roundDivHalfAway(n, d int64) int64 {
	if d < 0 {
		n = -n
		d = -d
	}
	if n >= 0 {
		q := n / d
		r := n % d
		if 2*r >= d {
			q++
		}
		return q
	}
	an := -n
	q := an / d
	r := an % d
	if 2*r >= d {
		q++
	}
	return -q
}

func PROCESSPARA() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	f10 := TempRecData.TcF.Shift(1).Truncate(0).IntPart()
	N := (f10 - 320) * 50
	c100 := roundDivHalfAway(N, 9)
	// store into S9(3)V99 : keep low-order digits
	ac := c100
	sign := int64(1)
	if ac < 0 {
		sign = -1
		ac = -ac
	}
	ac = ac % 100000
	c100 = sign * ac
	if c100 == 0 {
		WsC = decimal.New(0, 0)
	} else {
		WsC = decimal.New(c100, -2)
	}
	if WsC.Sign() < 0 {
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100
	WsFEd = formatFEd(TempRecData.TcF)
	WsCEd = formatCEd(WsC)
	fmt.Printf("%s %sF %sC\n", TempRecData.TcSensor, WsFEd, WsCEd)
	READPARA()
}

func MAINPARA() {
	var err error
	tempFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer tempFile.Close()
	tempReader = bufio.NewReader(tempFile)
	READPARA()
	for !(WsEofFlag == "Y") {
		PROCESSPARA()
	}
	fmt.Printf("%s%s%s%s\n", "READINGS: ", formatPic99(WsCount), " BELOW ZERO: ", formatPic99(WsFreeze)))
}

func main() {
	WsEofFlag = "N"
	WsC = decimal.New(0, 0)
	WsFreeze = 0
	WsCount = 0
	WsFEd = ""
	WsCEd = ""
	MAINPARA()
}

